def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bars = [r for r,row in enumerate(grid) if all(v == 8 for v in row)]
    col_bars = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_runs=[]; a=0
    for b in row_bars:
        row_runs.append((a,b)); a=b+1
    col_runs=[]; a=0
    for b in col_bars:
        col_runs.append((a,b)); a=b+1
    # Trailing partial strips are padding; the cells are the runs preceding divider bars.
    nr, nc = len(row_bars), len(col_bars)
    cell_color={}
    markers={}
    for r in range(nr):
        for c in range(nc):
            r0,r1=row_runs[r]; c0,c1=col_runs[c]
            for y in range(r0,r1):
                for x in range(c0,c1):
                    v=grid[y][x]
                    if v not in (0,8): markers.setdefault(v,[]).append((r,c))
    for color, cells in markers.items():
        for i,(r1,c1) in enumerate(cells):
            for r2,c2 in cells[i+1:]:
                if r1 == r2:
                    for c in range(min(c1,c2),max(c1,c2)+1):
                        cell_color.setdefault((r1,c),set()).add(color)
                if c1 == c2:
                    for r in range(min(r1,r2),max(r1,r2)+1):
                        cell_color.setdefault((r,c1),set()).add(color)
    out=[row[:] for row in grid]
    for (r,c), colors in cell_color.items():
        fill=next(iter(colors)) if len(colors)==1 else 6
        r0,r1=row_runs[r]; c0,c1=col_runs[c]
        for y in range(r0,r1):
            for x in range(c0,c1): out[y][x]=fill
    return out

